head.script:
let isFilter = false;
let isSort = false;



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > E > onrowstatuschange]<br/>DataList 모듈에서 Row 의 상태값이 변경되면 발생합니다.",
    "validation" : [
        "remove 계열의 메소드로 Row 가 '제거' 된 경우엔 onrowstatuschange 이벤트가 발생하지 않습니다.",
        "Row 가 '삽입' 되거나 전체 데이터가 로드된 경우엔 onrowstatuschange 이벤트가 발생하지 않습니다.",
        "deleteRows() 메소드로 여러 건의 Row 를 '삭제' 한 경우 onrowstatuschange 이벤트가 Row 갯수만큼 발생합니다.",
        "modifyAllStatus() 와 같은 메소드로 한 번에 여러 Row 의 상태를 변경할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // event 바인딩    
    target1.bind("onrowstatuschange", function(info){
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onrowstatuschange=====");
        wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
        for (var i=0; i<info.length; i++) {        
            wf_body_bottom.getObj("scwin").setReturnValue("info["+i+"].rowIndex : " + info[i].rowIndex);
            wf_body_bottom.getObj("scwin").setReturnValue("info["+i+"].oldRowStatus : " + info[i].oldRowStatus);
            wf_body_bottom.getObj("scwin").setReturnValue("info["+i+"].newRowStatus : " + info[i].newRowStatus);
        }        
    });      

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');

    isFilter = false;
    isSort = false;
}   



scwin.btn_removeRow_onclick = function (e) {
    target1.removeRow();
};



scwin.btn_insertRow_onclick = function (e) {
    target1.insertRow();
};



scwin.btn_setData_onclick = function (e) {     
    target1.setData(["setcol1","setcol2","setcol3","setcol4", "setcol5","setcol6","setcol7","setcol8"]);
};



scwin.btn_modifyAllStatus_onclick = function (e) {
    target1.modifyAllStatus("U");
};



scwin.btn_deleteRows_onclick = function (e) {
    target1.deleteRows([0, 1]);
};
